[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Amazon Product Catalog Performance &amp; Customer Sentiment Analysis</title>
<style>
  :root {
    --navy:   #0f2744;
    --blue:   #1a56db;
    --sky:    #3b82f6;
    --teal:   #0891b2;
    --green:  #16a34a;
    --amber:  #d97706;
    --red:    #dc2626;
    --slate:  #475569;
    --light:  #f8fafc;
    --border: #e2e8f0;
    --text:   #1e293b;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; background: #f1f5f9; color: var(--text); font-size: 14px; line-height: 1.55; }
  a { color: var(--blue); }

  /* ── header ── */
  .report-header {
    background: linear-gradient(135deg, var(--navy) 0%, #1e3a5f 60%, #1a56db 100%);
    color: #fff; padding: 48px 56px 40px;
  }
  .report-header .eyebrow { font-size: 11px; letter-spacing: 2px; text-transform: uppercase; opacity: .7; margin-bottom: 10px; }
  .report-header h1 { font-size: 28px; font-weight: 700; line-height: 1.25; max-width: 680px; }
  .report-header .meta { margin-top: 14px; font-size: 12px; opacity: .65; }

  /* ── layout ── */
  .content { max-width: 1180px; margin: 0 auto; padding: 40px 32px 64px; }
  .section { background: #fff; border-radius: 12px; border: 1px solid var(--border); padding: 32px 36px; margin-bottom: 28px; }
  .section-title {
    font-size: 18px; font-weight: 700; color: var(--navy); margin-bottom: 6px;
    padding-bottom: 14px; border-bottom: 2px solid var(--border);
  }
  .section-subtitle { font-size: 13px; color: var(--slate); margin-bottom: 22px; margin-top: 4px; }

  /* ── KPI grid ── */
  .kpi-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; margin-top: 4px; }
  .kpi-card {
    background: var(--light); border: 1px solid var(--border); border-radius: 10px;
    padding: 18px 16px 14px; text-align: center; position: relative; overflow: hidden;
  }
  .kpi-card::before {
    content: ''; position: absolute; top: 0; left: 0; right: 0; height: 4px;
  }
  .kpi-card.c-blue::before   { background: var(--blue); }
  .kpi-card.c-teal::before   { background: var(--teal); }
  .kpi-card.c-green::before  { background: var(--green); }
  .kpi-card.c-amber::before  { background: var(--amber); }
  .kpi-card.c-red::before    { background: var(--red); }
  .kpi-value { font-size: 30px; font-weight: 800; color: var(--navy); line-height: 1.1; }
  .kpi-label { font-size: 11px; color: var(--slate); margin-top: 5px; text-transform: uppercase; letter-spacing: .6px; }
  .kpi-note  { font-size: 11px; color: var(--slate); margin-top: 6px; }

  /* ── insight boxes ── */
  .insight-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-top: 22px; }
  .insight-box {
    background: #eff6ff; border-left: 4px solid var(--blue); border-radius: 6px;
    padding: 14px 16px; font-size: 13px;
  }
  .insight-box.amber { background: #fffbeb; border-color: var(--amber); }
  .insight-box.green { background: #f0fdf4; border-color: var(--green); }
  .insight-box.red   { background: #fef2f2; border-color: var(--red); }
  .insight-title { font-weight: 700; margin-bottom: 4px; font-size: 12px; text-transform: uppercase; letter-spacing: .5px; color: var(--slate); }

  /* ── tables ── */
  table { width: 100%; border-collapse: collapse; font-size: 13px; }
  thead th { background: #f8fafc; color: var(--slate); font-size: 11px; text-transform: uppercase; letter-spacing: .5px; padding: 10px 12px; text-align: left; border-bottom: 2px solid var(--border); }
  tbody tr { border-bottom: 1px solid #f1f5f9; }
  tbody tr:hover { background: #f8fafc; }
  tbody td { padding: 10px 12px; }
  .badge { display: inline-block; padding: 2px 8px; border-radius: 99px; font-size: 11px; font-weight: 600; }
  .badge-green { background: #dcfce7; color: #166534; }
  .badge-amber { background: #fef9c3; color: #854d0e; }
  .badge-red   { background: #fee2e2; color: #991b1b; }
  .badge-blue  { background: #dbeafe; color: #1e40af; }

  /* ── charts ── */
  .chart-row { display: grid; gap: 24px; margin-top: 24px; }
  .chart-row-2 { grid-template-columns: 1fr 1fr; }
  .chart-row-3 { grid-template-columns: 1fr 1fr 1fr; }
  .chart-box { background: var(--light); border: 1px solid var(--border); border-radius: 10px; padding: 20px 18px; }
  .chart-title { font-size: 13px; font-weight: 700; color: var(--navy); margin-bottom: 16px; }
  .chart-box svg { display: block; width: 100%; }

  /* ── bar chart helpers ── */
  .bar-chart { display: flex; flex-direction: column; gap: 8px; }
  .bar-row { display: flex; align-items: center; gap: 10px; }
  .bar-label { font-size: 12px; color: var(--slate); min-width: 130px; text-align: right; }
  .bar-label-left { font-size: 12px; color: var(--slate); min-width: 90px; }
  .bar-track { flex: 1; background: #e2e8f0; border-radius: 4px; height: 22px; position: relative; overflow: hidden; }
  .bar-fill { height: 100%; border-radius: 4px; display: flex; align-items: center; justify-content: flex-end; padding-right: 6px; font-size: 11px; font-weight: 700; color: #fff; transition: width .3s; }
  .bar-fill-blue  { background: var(--blue); }
  .bar-fill-teal  { background: var(--teal); }
  .bar-fill-green { background: var(--green); }
  .bar-fill-amber { background: var(--amber); }
  .bar-fill-red   { background: var(--red); }
  .bar-fill-navy  { background: var(--navy); }
  .bar-fill-sky   { background: var(--sky); }
  .bar-value { font-size: 12px; color: var(--text); min-width: 36px; }

  /* ── donut ── */
  .donut-wrap { display: flex; align-items: center; gap: 24px; }
  .donut-legend { display: flex; flex-direction: column; gap: 8px; flex: 1; }
  .legend-row { display: flex; align-items: center; gap: 8px; font-size: 12px; }
  .legend-dot { width: 12px; height: 12px; border-radius: 3px; flex-shrink: 0; }

  /* ── sentiment ── */
  .sentiment-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 12px; }
  .sentiment-box h4 { font-size: 13px; font-weight: 700; margin-bottom: 12px; }
  .tag-cloud { display: flex; flex-wrap: wrap; gap: 7px; }
  .tag {
    padding: 4px 12px; border-radius: 99px; font-size: 12px; font-weight: 600;
    cursor: default;
  }
  .tag-pos { background: #dcfce7; color: #166534; }
  .tag-neg { background: #fee2e2; color: #991b1b; }

  /* ── recommendations ── */
  .rec-list { display: flex; flex-direction: column; gap: 16px; margin-top: 8px; }
  .rec-card {
    border: 1px solid var(--border); border-radius: 8px; padding: 18px 20px;
    display: flex; gap: 16px; align-items: flex-start;
  }
  .rec-num {
    width: 32px; height: 32px; border-radius: 50%; background: var(--blue); color: #fff;
    font-weight: 800; font-size: 14px; display: flex; align-items: center; justify-content: center;
    flex-shrink: 0;
  }
  .rec-num.amber { background: var(--amber); }
  .rec-num.green { background: var(--green); }
  .rec-num.teal  { background: var(--teal); }
  .rec-num.red   { background: var(--red); }
  .rec-content h4 { font-size: 14px; font-weight: 700; margin-bottom: 4px; color: var(--navy); }
  .rec-content p  { font-size: 13px; color: var(--slate); line-height: 1.5; }
  .rec-content .data-tag {
    display: inline-block; background: #eff6ff; color: var(--blue); font-size: 11px;
    padding: 2px 8px; border-radius: 4px; font-weight: 600; margin-top: 6px;
  }

  /* ── footer ── */
  .report-footer { text-align: center; color: #94a3b8; font-size: 11px; margin-top: 32px; padding-bottom: 20px; }

  @media (max-width: 900px) {
    .kpi-grid { grid-template-columns: repeat(3,1fr); }
    .chart-row-2, .chart-row-3 { grid-template-columns: 1fr; }
    .insight-row { grid-template-columns: 1fr; }
    .sentiment-cols { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>

<div class="report-header">
  <div class="eyebrow">Analytics Report</div>
  <h1>Amazon Product Catalog Performance &amp; Customer Sentiment Analysis</h1>
  <div class="meta">Dataset: 1,465 Amazon India products &nbsp;|&nbsp; Analysis Date: April 2026 &nbsp;|&nbsp; Audience: Product &amp; Category Management</div>
</div>

<div class="content">

<!-- ═══════════════════════════════════════════
     SECTION 1 — EXECUTIVE OVERVIEW
════════════════════════════════════════════ -->
<div class="section">
  <div class="section-title">Executive Overview</div>
  <div class="section-subtitle">Headline KPIs across the full 1,465-product catalog</div>

  <div class="kpi-grid">
    <div class="kpi-card c-blue">
      <div class="kpi-value">1,465</div>
      <div class="kpi-label">Products Analyzed</div>
      <div class="kpi-note">4 primary categories</div>
    </div>
    <div class="kpi-card c-teal">
      <div class="kpi-value">4.10</div>
      <div class="kpi-label">Avg Customer Rating</div>
      <div class="kpi-note">out of 5.0</div>
    </div>
    <div class="kpi-card c-amber">
      <div class="kpi-value">47.7%</div>
      <div class="kpi-label">Avg Discount</div>
      <div class="kpi-note">median ₹-off varies by cat.</div>
    </div>
    <div class="kpi-card c-green">
      <div class="kpi-value">75.8%</div>
      <div class="kpi-label">High-Rating Share</div>
      <div class="kpi-note">products rated ≥ 4.0</div>
    </div>
    <div class="kpi-card c-red">
      <div class="kpi-value">5,179</div>
      <div class="kpi-label">Median Rating Count</div>
      <div class="kpi-note">per product (engagement)</div>
    </div>
  </div>

  <div class="insight-row">
    <div class="insight-box green">
      <div class="insight-title">Catalog Health</div>
      Nearly <strong>3 in 4 products</strong> carry a rating of 4.0 or higher, signaling a broadly well-curated catalog with limited quality drag.
    </div>
    <div class="insight-box amber">
      <div class="insight-title">Discount–Satisfaction Link</div>
      Correlation between discount depth and rating is <strong>−0.155</strong> — deeper discounts are modestly associated with <em>lower</em> satisfaction, not higher. Discounts do not substitute for product quality.
    </div>
    <div class="insight-box blue">
      <div class="insight-title">Engagement Leader</div>
      Electronics drives the highest median review count (10,689/product), more than 4× the Home &amp; Kitchen median (2,305), indicating much stronger buyer engagement in tech categories.
    </div>
    <div class="insight-box red">
      <div class="insight-title">Weak Spots</div>
      Remote Controls (avg 3.80★), Fan Heaters (3.81★), and Electric Heaters (3.89★) are consistent underperformers by customer rating and demand targeted quality review.
    </div>
  </div>
</div>

<!-- ═══════════════════════════════════════════
     SECTION 2 — CATEGORY PERFORMANCE
════════════════════════════════════════════ -->
<div class="section">
  <div class="section-title">Category Performance Breakdown</div>
  <div class="section-subtitle">Top-level and sub-category rankings by avg rating and customer engagement (products with ≥10 items per category)</div>

  <div class="chart-row chart-row-2">

    <!-- Category Avg Rating bar chart -->
    <div class="chart-box">
      <div class="chart-title">Avg Rating by Top-Level Category</div>
      <div class="bar-chart">
        <div class="bar-row">
          <div class="bar-label">Office Products</div>
          <div class="bar-track"><div class="bar-fill bar-fill-green" style="width:86.2%">4.31</div></div>
          <div class="bar-value">31 products</div>
        </div>
        <div class="bar-row">
          <div class="bar-label">Computers &amp; Acc.</div>
          <div class="bar-track"><div class="bar-fill bar-fill-blue" style="width:83.1%">4.15</div></div>
          <div class="bar-value">453 products</div>
        </div>
        <div class="bar-row">
          <div class="bar-label">Electronics</div>
          <div class="bar-track"><div class="bar-fill bar-fill-sky" style="width:81.6%">4.08</div></div>
          <div class="bar-value">526 products</div>
        </div>
        <div class="bar-row">
          <div class="bar-label">Home &amp; Kitchen</div>
          <div class="bar-track"><div class="bar-fill bar-fill-amber" style="width:80.8%">4.04</div></div>
          <div class="bar-value">448 products</div>
        </div>
      </div>
      <p style="font-size:11px;color:#94a3b8;margin-top:14px;">Bar length proportional to 5-star scale (60–90% range shown).</p>
    </div>

    <!-- Median review count -->
    <div class="chart-box">
      <div class="chart-title">Median Rating Count (Engagement) by Category</div>
      <div class="bar-chart">
        <div class="bar-row">
          <div class="bar-label">Electronics</div>
          <div class="bar-track"><div class="bar-fill bar-fill-blue" style="width:100%">10,689</div></div>
        </div>
        <div class="bar-row">
          <div class="bar-label">Computers &amp; Acc.</div>
          <div class="bar-track"><div class="bar-fill bar-fill-teal" style="width:72.3%">7,732</div></div>
        </div>
        <div class="bar-row">
          <div class="bar-label">Office Products</div>
          <div class="bar-track"><div class="bar-fill bar-fill-green" style="width:41.4%">4,426</div></div>
        </div>
        <div class="bar-row">
          <div class="bar-label">Home &amp; Kitchen</div>
          <div class="bar-track"><div class="bar-fill bar-fill-amber" style="width:21.6%">2,306</div></div>
        </div>
      </div>
      <p style="font-size:11px;color:#94a3b8;margin-top:14px;">Electronics and Computers generate 3–5× more reviews than Home &amp; Kitchen, reflecting higher buyer intent and research behaviour.</p>
    </div>
  </div>

  <!-- Sub-category table: top performers -->
  <h4 style="margin-top:28px;margin-bottom:12px;font-size:14px;color:var(--navy);">Top Sub-Category Performers (avg rating, ≥15 products)</h4>
  <table>
    <thead>
      <tr>
        <th>#</th>
        <th>Sub-Category</th>
        <th>Products</th>
        <th>Avg Rating</th>
        <th>Avg Discount</th>
        <th>Median Reviews</th>
        <th>Status</th>
      </tr>
    </thead>
    <tbody>
      <tr><td>1</td><td>Mice</td><td>24</td><td>4.29</td><td>42.0%</td><td>8,767</td><td><span class="badge badge-green">Top Performer</span></td></tr>
      <tr><td>2</td><td>HDMI Cables</td><td>24</td><td>4.25</td><td>59.8%</td><td>10,962</td><td><span class="badge badge-green">Top Performer</span></td></tr>
      <tr><td>3</td><td>Smart Televisions</td><td>63</td><td>4.21</td><td>38.3%</td><td>6,088</td><td><span class="badge badge-green">Top Performer</span></td></tr>
      <tr><td>4</td><td>USB Cables</td><td>233</td><td>4.15</td><td>59.4%</td><td>6,255</td><td><span class="badge badge-blue">Strong</span></td></tr>
      <tr><td>5</td><td>Wall Chargers</td><td>16</td><td>4.14</td><td>51.4%</td><td>5,477</td><td><span class="badge badge-blue">Strong</span></td></tr>
      <tr><td>6</td><td>Dry Irons</td><td>24</td><td>4.13</td><td>34.3%</td><td>5,878</td><td><span class="badge badge-blue">Strong</span></td></tr>
      <tr><td>7</td><td>Smartphones</td><td>68</td><td>4.10</td><td>23.3%</td><td>18,998</td><td><span class="badge badge-blue">Strong</span></td></tr>
    </tbody>
  </table>

  <h4 style="margin-top:28px;margin-bottom:12px;font-size:14px;color:var(--navy);">Bottom Sub-Category Performers (avg rating, ≥15 products)</h4>
  <table>
    <thead>
      <tr>
        <th>#</th>
        <th>Sub-Category</th>
        <th>Products</th>
        <th>Avg Rating</th>
        <th>Avg Discount</th>
        <th>Median Reviews</th>
        <th>Status</th>
      </tr>
    </thead>
    <tbody>
